function(container, apiUrl, tables) {
  // 自動保存の状態管理
  let autoSaveInterval = null;
  let localData = JSON.parse(localStorage.getItem('workRecordLocalData') || '[]');

  // ローカルデータテーブル再描画
  function renderLocalData(data) {
    const tbody = container.querySelector('#local-data-tbody');
    tbody.innerHTML = data.map(item => `
      <tr data-id="${item.id}">
        <td>${item.id.substring(0, 8)}...</td>
        <td>${item.workerName || '未設定'}</td>
        <td>${item.workContent || '作業内容未入力'}</td>
        <td>${new Date(item.savedAt).toLocaleString()}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 11px; ${item.synced ? 'background: rgba(34,197,94,0.2); color: #22c55e;' : 'background: rgba(239,68,68,0.2); color: #ef4444;'}">
            ${item.synced ? '同期済み' : '同期待ち'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary sync-btn" data-id="${item.id}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">同期</button>
          <button class="action-btn secondary delete-local-btn" data-id="${item.id}" style="background: transparent; color: #ef4444; border: 1px solid rgba(239,68,68,0.3); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // ネットワーク状態チェック
  function updateNetworkStatus() {
    const statusEl = container.querySelector('#network-status');
    if (navigator.onLine) {
      statusEl.textContent = 'オンライン';
      statusEl.style.color = '#22c55e';
    } else {
      statusEl.textContent = 'オフライン';
      statusEl.style.color = '#ef4444';
    }
  }

  // 同期待ちデータ件数更新
  function updatePendingCount() {
    const pendingCount = localData.filter(item => !item.synced).length;
    container.querySelector('#pending-sync-count').textContent = `${pendingCount}件`;
  }

  // エラー表示
  function showError(message) {
    const errorEl = container.querySelector('#error-notification');
    const messageEl = container.querySelector('#error-message');
    messageEl.textContent = message;
    errorEl.style.display = 'block';
  }

  // 自動保存処理
  function startAutoSave() {
    const interval = parseInt(container.querySelector('#save-interval').value) * 1000;

    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
    }

    autoSaveInterval = setInterval(async () => {
      // 未保存の作業記録データがあるかチェック（実際の実装では現在の入力状態をチェック）
      const unsavedData = {
        id: 'temp_' + Date.now(),
        workerName: '現在のユーザー',
        workContent: '自動保存データ',
        savedAt: new Date().toISOString(),
        synced: false
      };

      // ローカルストレージに保存
      localData.push(unsavedData);
      localStorage.setItem('workRecordLocalData', JSON.stringify(localData));

      // 最終保存時刻更新
      container.querySelector('#last-save-time').textContent = new Date().toLocaleString();

      // 表示更新
      renderLocalData(localData);
      updatePendingCount();

      // オンラインの場合は同期を試行
      if (navigator.onLine) {
        await syncPendingData();
      }
    }, interval);

    container.querySelector('#auto-save-status').textContent = '有効';
    container.querySelector('#auto-save-status').style.color = 'var(--primary)';
  }

  // 同期処理
  async function syncPendingData() {
    const pendingItems = localData.filter(item => !item.synced);

    for (const item of pendingItems) {
      try {
        // 作業記録テーブルに保存（tableIndex = 1）
        const saved = await window.aivicApi.save(1, {
          作業員ID: 'user_001',
          作業日: new Date().toISOString(),
          作業開始時刻: new Date().toISOString(),
          作業時間: 60,
          プロジェクト名: 'プロジェクトA',
          作業場所: '現場A',
          作業種別: '設置',
          作業内容: item.workContent,
          進捗状況: '作業中',
          承認状態: '未承認',
          作成者ID: 'user_001'
        });

        if (saved) {
          // 同期成功
          item.synced = true;
        }
      } catch (error) {
        showError(`データ同期エラー: ${error.message}`);
        break;
      }
    }

    localStorage.setItem('workRecordLocalData', JSON.stringify(localData));
    renderLocalData(localData);
    updatePendingCount();
  }

  // 初期化
  renderLocalData(localData);
  updateNetworkStatus();
  updatePendingCount();
  startAutoSave();

  // ネットワーク状態監視
  window.addEventListener('online', updateNetworkStatus);
  window.addEventListener('offline', updateNetworkStatus);

  // 手動同期ボタン
  container.querySelector('#btn-manual-sync').addEventListener('click', async () => {
    await syncPendingData();
  });

  // 保存間隔変更
  container.querySelector('#save-interval').addEventListener('change', () => {
    startAutoSave();
  });

  // エラー通知閉じる
  container.querySelector('#btn-dismiss-error').addEventListener('click', () => {
    container.querySelector('#error-notification').style.display = 'none';
  });

  // 検索機能
  container.querySelector('#btn-search-local').addEventListener('click', () => {
    const keyword = container.querySelector('#search-local-data').value.toLowerCase();
    const filtered = localData.filter(item => 
      JSON.stringify(item).toLowerCase().includes(keyword)
    );
    renderLocalData(filtered);
  });

  // ローカルデータ操作
  container.addEventListener('click', async (e) => {
    const syncBtn = e.target.closest('.sync-btn');
    const deleteBtn = e.target.closest('.delete-local-btn');

    if (syncBtn) {
      const id = syncBtn.dataset.id;
      const item = localData.find(item => item.id === id);
      if (item && !item.synced) {
        try {
          const saved = await window.aivicApi.save(1, {
            作業員ID: 'user_001',
            作業日: new Date().toISOString(),
            作業開始時刻: new Date().toISOString(),
            作業時間: 60,
            プロジェクト名: 'プロジェクトA',
            作業場所: '現場A',
            作業種別: '設置',
            作業内容: item.workContent,
            進捗状況: '作業中',
            承認状態: '未承認',
            作成者ID: 'user_001'
          });

          if (saved) {
            item.synced = true;
            localStorage.setItem('workRecordLocalData', JSON.stringify(localData));
            renderLocalData(localData);
            updatePendingCount();
          }
        } catch (error) {
          showError(`同期エラー: ${error.message}`);
        }
      }
    }

    if (deleteBtn) {
      if (!confirm('このローカルデータを削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      localData = localData.filter(item => item.id !== id);
      localStorage.setItem('workRecordLocalData', JSON.stringify(localData));
      renderLocalData(localData);
      updatePendingCount();
    }
  });

  // バックアップ機能
  container.querySelector('#btn-backup-local').addEventListener('click', () => {
    const dataStr = JSON.stringify(localData, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `work_record_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  });

  // 復元機能
  container.querySelector('#btn-restore-backup').addEventListener('click', () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = (e) => {
      const file = e.target.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (e) => {
          try {
            const restoredData = JSON.parse(e.target.result);
            localData = restoredData;
            localStorage.setItem('workRecordLocalData', JSON.stringify(localData));
            renderLocalData(localData);
            updatePendingCount();
            alert('バックアップから復元しました');
          } catch (error) {
            showError('バックアップファイルの形式が正しくありません');
          }
        };
        reader.readAsText(file);
      }
    };
    input.click();
  });

  // ローカルデータクリア
  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (!confirm('すべてのローカルデータを削除しますか？この操作は取り消せません。')) return;

    localData = [];
    localStorage.setItem('workRecordLocalData', JSON.stringify(localData));
    renderLocalData(localData);
    updatePendingCount();
  });

  // 設定変更ボタン（設定画面への遷移）
  container.querySelector('#btn-settings').addEventListener('click', () => {
    // 設定画面が存在する場合の遷移（現在は該当画面がないためアラート）
    alert('保存設定の詳細変更機能は今後実装予定です');
  });
}
